function EXACT_RANK(A):
    r <- 0
    for each column c of A:
        find pivot row i >= r with A[i][c] != 0; if none, continue
        swap rows r and i; scale row r so A[r][c] = 1
        eliminate column c from all other rows
        r <- r + 1
    return r

function BETTI_NUMBER(d1, d2, dim_C1):
    assert d1 . d2 = 0            # genuine chain complex
    return dim_C1 - EXACT_RANK(d1) - EXACT_RANK(d2)

