from fractions import Fraction
from typing import List

Matrix = List[List[Fraction]]


def exact_rank(matrix: Matrix) -> int:
    """Exact rank of a rational matrix via Gauss-Jordan elimination."""
    if not matrix or not matrix[0]:
        return 0
    a = [row[:] for row in matrix]
    rows, cols, r = len(a), len(a[0]), 0
    for c in range(cols):
        piv = next((i for i in range(r, rows) if a[i][c] != 0), None)
        if piv is None:
            continue
        a[r], a[piv] = a[piv], a[r]
        inv = Fraction(1) / a[r][c]
        a[r] = [x * inv for x in a[r]]
        for i in range(rows):
            if i != r and a[i][c] != 0:
                f = a[i][c]
                a[i] = [x - f * y for x, y in zip(a[i], a[r])]
        r += 1
    return r


def betti_number(d1: Matrix, d2: Matrix, dim_c1: int) -> int:
    """Middle Betti number via the exact formula dim H = dim C1 - rank d1 - rank d2.

    d1 : C1 -> C0 (rows = dim C0, cols = dim C1);
    d2 : C2 -> C1 (rows = dim C1, cols = dim C2). Requires d1 . d2 = 0.
    """
    return dim_c1 - exact_rank(d1) - exact_rank(d2)

