from typing import List


def activation_pattern_count(widths: List[int]) -> int:
    """P(w) = prod_i 2^{w_i} = 2^{sum_i w_i}, the activation-pattern count of a
    network with hidden-layer widths `widths`. Runs in O(L) big-integer steps."""
    total = 1
    for w in widths:
        total *= 2 ** w
    return total


def width_bound_on_betti(dim_c1: int, widths: List[int]) -> int:
    """Return the monotone width bound min(dim_c1, P(w)) as an upper bound on the
    middle Betti number of the decision surface, given a cell count `dim_c1`."""
    return min(dim_c1, activation_pattern_count(widths))

