function SCALAR_RELU_DECISION_SURFACE(layer_w, layer_b, out_w, out_b):
    define f(x) = out_b + sum_j out_w[j]*relu(layer_w[j]*x+layer_b[j])
    breaks <- sorted( -layer_b[j]/layer_w[j] : layer_w[j] != 0 )
    [lo, hi] <- interval enclosing all breaks
    zeros <- empty list
    for consecutive samples p,q in a fine grid on [lo,hi]:
        if sign(f(p)) != sign(f(q)):
            append midpoint(p,q) to zeros
    return (breaks, zeros)

