from typing import Callable, List, Tuple


def scalar_relu_decision_surface(
    layer_w: List[float],
    layer_b: List[float],
    out_w: List[float],
    out_b: float,
    samples: int = 4000,
) -> Tuple[List[float], List[float]]:
    """Locate the activation-region boundaries and the zero-cells of the decision
    surface V(f) = {x : f(x) = 0} for a scalar single-hidden-layer ReLU network

        f(x) = out_b + sum_j out_w[j] * relu(layer_w[j] * x + layer_b[j]).

    Returns (breakpoints, zero_crossings). Complexity O(width + samples)."""
    def relu(t: float) -> float:
        return t if t > 0 else 0.0

    def f(x: float) -> float:
        return out_b + sum(o * relu(w * x + b)
                           for o, w, b in zip(out_w, layer_w, layer_b))

    breaks = sorted(-b / w for w, b in zip(layer_w, layer_b) if w != 0)
    lo = (breaks[0] - 1.0) if breaks else -1.0
    hi = (breaks[-1] + 1.0) if breaks else 1.0
    grid = [lo + (hi - lo) * k / samples for k in range(samples + 1)]
    zeros: List[float] = []
    for p, q in zip(grid, grid[1:]):
        if (f(p) <= 0) != (f(q) <= 0):
            zeros.append(0.5 * (p + q))
    return breaks, zeros
